import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Printed entry/evolution abilities: origin, optional choice, ownership and resumable effects. */
public final class StarterDeck100EntryTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String text){StarterDeck100PokemonTest.check(ok,text);}
    static CardInstance hand(ServerMatch m,String id){return StarterDeck100PokemonTest.hand(m,id);}
    static void accept(ServerMatch m){var p=m.triggerOrderPrompt();check(p!=null&&p.optionalDecision()&&p.choosingPlayer().equals(A),"entry optional decision missing");TopDeckLookTest.rejects(()->m.decideTriggeredEffect(B,p.id(),true));m.decideTriggeredEffect(A,p.id(),true);}
    static UUID evolveBench(ServerMatch m,int number){UUID host=m.benchPokemonView(A).getFirst().pokemonId();var chain=StarterDeck100PokemonTest.chain(id(number));for(var stage:chain.subList(1,chain.size())){m.evolveByEffect(A,host,hand(m,stage).instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);if(!stage.equals(id(number)))StarterDeck100PokemonTest.declineEntryTriggers(m);}return host;}
    public static void main(String[] args){scales();frostOver();drawEvolution();darkSignal();ballSearch();hiddenClaw();System.out.println("StarterDeck100EntryTest passed: seven printed entry abilities, hand origin, optional decisions, public Tool ownership and private selections");}
    static void scales(){var m=StarterDeck100PokemonTest.game(4);check(m.activePokemonView(B).conditions().isEmpty(),"fixture failed to decline Scales");evolveBench(m,4);check(m.activePokemonView(B).conditions().isEmpty(),"Scales applied before optional choice");accept(m);check(m.activePokemonView(B).conditions().containsAll(Set.of(SpecialCondition.POISONED,SpecialCondition.BURNED,SpecialCondition.CONFUSED)),"Scales did not apply all three conditions");}
    static void frostOver(){var m=StarterDeck100PokemonTest.game(99);var water=hand(m,"sd100_cn_water_energy");m.discardHandCardsByEffect(A,A,List.of(water.instanceId()));evolveBench(m,99);accept(m);StarterDeck100PokemonTest.select(m,1);var dest=m.effectAttachmentPrompt(A);m.chooseEffectAttachmentTarget(A,dest.resolutionId(),dest.step(),m.activePokemonView(A).pokemonId());check(m.activePokemonView(A).attachedEnergyIds().contains(water.instanceId()),"Frost Over did not attach discarded Basic Water");StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().baseDamage()==90&&!m.mayAttack(A),"Crystal Breath printed damage or next-turn lock");}
    static void drawEvolution(){for(int n:List.of(250,251)){var m=StarterDeck100PokemonTest.game(n);int before=m.privateView(A).hand().size();evolveBench(m,n);int afterEvolution=m.privateView(A).hand().size();accept(m);check(m.privateView(A).hand().size()==afterEvolution+(n==250?2:3),"evolution draw incorrect");check(m.triggerOrderPrompt()==null,"entry ability repeated without another evolution");}}
    static void darkSignal(){var m=StarterDeck100PokemonTest.game(256);UUID original=m.activePokemonView(B).pokemonId(),bench=m.benchPokemonView(B).getFirst().pokemonId();evolveBench(m,256);accept(m);var p=m.effectPokemonPrompt(A);check(p!=null&&p.targets().size()==1&&p.targets().getFirst().pokemonId().equals(bench),"Dark Signal not controller choice of opposing Bench");StarterDeck100PokemonTest.choosePokemon(m,bench);check(m.activePokemonView(B).pokemonId().equals(bench)&&m.benchPokemonView(B).stream().anyMatch(x->x.pokemonId().equals(original)),"Dark Signal failed to switch opponent");}
    static void ballSearch(){var m=StarterDeck100PokemonTest.game(153,id(379),id(373));check(m.triggerOrderPrompt()==null,"opening triggered Ball Search");var fromDeck=m.privateView(A).deck().stream().filter(c->c.definitionId().equals(id(153))).findFirst().orElseThrow();m.putBasicPokemonFromOwnDeckToBenchByEffect(A,fromDeck.instanceId());check(m.triggerOrderPrompt()==null,"deck entry triggered Ball Search");var fromDiscard=hand(m,id(153));m.discardHandCardsByEffect(A,A,List.of(fromDiscard.instanceId()));m.putBasicPokemonFromDiscardToBenchByEffect(A,A,fromDiscard.instanceId());check(m.triggerOrderPrompt()==null,"discard entry triggered Ball Search");var poke=hand(m,id(379));var great=hand(m,id(373));m.discardHandCardsByEffect(A,A,List.of(poke.instanceId(),great.instanceId()));m.playBasicPokemonToBench(A,hand(m,id(153)).instanceId());accept(m);var p=m.effectCardPrompt(A);check(p.candidates().equals(List.of(poke)),"Ball Search first choice not Poke Ball");StarterDeck100PokemonTest.select(m,1);p=m.effectCardPrompt(A);check(p.candidates().equals(List.of(great)),"Ball Search second choice not Great Ball");StarterDeck100PokemonTest.select(m,1);check(m.privateView(A).hand().containsAll(List.of(poke,great)),"Ball Search did not recover both cards");}
    static ServerMatch toolGame(){for(int seed=0;seed<200;seed++){var m=new ServerMatch(A,B,StarterDeck100PokemonTest.deck(A,273,"zsv10-5_en_079"),StarterDeck100PokemonTest.deck(B,1,"zsv10-5_en_079"),StarterDeck100CombatTest.RULE,StarterDeck100CombatTest.CARDS,StarterDeck100CombatTest.COMBAT,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(m.privateView(A).hand().stream().filter(c->c.definitionId().equals(id(273))).count()<2||m.privateView(B).hand().stream().filter(c->c.definitionId().equals(id(1))).count()<2)continue;OpeningTestSupport.complete(m,A,B,1);m.endTurn(A);m.endTurn(B);return m;}throw new AssertionError("Tool fixture");}
    static void hiddenClaw(){for(boolean opponent:List.of(false,true)){var m=toolGame();UUID owner=opponent?B:A;CardInstance tool;
        if(opponent){m.endTurn(A);tool=m.privateView(B).deck().stream().filter(c->c.definitionId().equals("zsv10-5_en_079")).findFirst().orElseThrow();m.searchOwnDeckToHandByEffect(B,List.of(tool.instanceId()));m.playTrainer(B,tool.instanceId(),m.activePokemonView(B).pokemonId());m.endTurn(B);}
        else {tool=hand(m,"zsv10-5_en_079");m.playTrainer(A,tool.instanceId(),m.activePokemonView(A).pokemonId());}
        m.playBasicPokemonToBench(A,hand(m,id(273)).instanceId());accept(m);var p=m.effectCardPrompt(A);check(p!=null&&p.candidates().equals(List.of(tool)),"Hidden Claw did not expose Tool from either field");TopDeckLookTest.rejects(()->m.effectCardPrompt(B));TopDeckLookTest.rejects(()->m.submitEffectCards(B,p.resolutionId(),p.step(),List.of(tool.instanceId())));TopDeckLookTest.rejects(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(UUID.randomUUID())));m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(tool.instanceId()));check(m.privateView(owner).discard().contains(tool)&&m.activePokemonView(owner).attachedTools().isEmpty(),"Tool not discarded to its owner");}}
}
